import {PLANTS,BALANCE,SUN_MAGNET} from './data.js';
import {MAP} from './map.js';
import {P} from './art/palette.js';
import {drawPlant} from './art/plants.js';
import {drawZombie} from './art/zombies.js';
import {drawBoss,drawTelegraph} from './art/bosses.js';
import {drawProjectile} from './art/projectiles.js';
import {drawEffect,drawSun,drawZone} from './art/effects.js';
import {drawTerrain,drawBase} from './art/environment.js';
import {VisualState} from './art/visualState.js';
import {line,oval,leaf,star,healthBar} from './art/shapes.js';
export {drawPlant} from './art/plants.js';
export {plantImage,bossImage} from './art/portraits.js';
const states=new WeakMap();

function drawEntity(c,v,state,T,inspected){const e=v.snapshot,o=state.options(v);if(v.died!==undefined)o.death=(state.time-v.died)/v.duration;if(v.kind==='plant'){drawPlant(c,e.id,v.x,v.y,.83,state.time,o);if(!o.death&&inspected?.uid===e.uid){c.strokeStyle=P.cream;c.lineWidth=2;c.strokeRect(v.x-18,v.y-20,36,42)}if(e.id==='potatoMine'&&o.arming<1){c.fillStyle=P.ink;c.font='bold 10px system-ui';c.textAlign='center';c.fillText(Math.round(o.arming*100)+'%',v.x,v.y+28)}}else if(e.bossId)drawBoss(c,e,v.x,v.y,state.time,o);else drawZombie(c,e,v.x,v.y,state.time,o);if(!o.death&&o.ratio<.999)healthBar(c,v.x,v.y+(e.bossId?36:26),e.bossId?48:27,o.ratio,v.kind==='plant'?P.light:P.damage)}
function drawSynergies(c,g,T){if(!g.upgrades.includes('crossfire')&&!g.upgrades.includes('bodyguard')&&!g.upgrades.includes('gardenAura')&&!Object.values(g.selectedEvolutions).includes('crossfireEvolution'))return;c.save();c.globalAlpha=.22;c.setLineDash([2,5]);for(const p of g.plants){if(p.hp<=0)continue;for(const q of g.adjacentPlants(p)){if(q.uid<p.uid)continue;const shooters=p.class==='shooter'&&q.class==='shooter'&&(g.upgrades.includes('crossfire')||g.selectedEvolutions.repeater==='crossfireEvolution'),guard=g.upgrades.includes('bodyguard')&&[p.id,q.id].includes('bonkChoy')&&[p.id,q.id].includes('wallNut'),heal=g.upgrades.includes('gardenAura')&&[p.id,q.id].includes('sunflower');if(shooters||guard||heal)line(c,[[(p.x+.5)*T,(p.y+.5)*T+15],[(q.x+.5)*T,(q.y+.5)*T+15]],heal?P.heal:guard?P.gold:P.cream,1.3)}}c.restore()}
function drawMagnetField(c,g,state,T){const level=Math.max(0,Math.min(SUN_MAGNET.levels.length-1,g.meta.gardenTools?.magnet||0)),config=SUN_MAGNET.levels[level];if(!config.radius||!g.pointer.active||g.paused||!['playing','intermission'].includes(g.state)||state.magnetField<.002)return;const x=g.pointer.x*T,y=g.pointer.y*T,r=config.radius*T;c.save();c.translate(x,y);c.globalAlpha=state.magnetField;const glow=c.createRadialGradient(0,0,4,0,0,r);glow.addColorStop(0,'#ffe77a55');glow.addColorStop(.72,'#ffd34a18');glow.addColorStop(1,'#ffd34a00');c.fillStyle=glow;c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.fill();c.globalAlpha*=.62;c.strokeStyle=P.sun;c.lineWidth=1;c.setLineDash([2,8]);c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.stroke();c.setLineDash([]);for(let i=0;i<level;i++){const a=state.time*(.65+i*.12)+i*Math.PI*2/Math.max(1,level);star(c,Math.cos(a)*r*(.46+i*.12),Math.sin(a)*r*(.46+i*.12),2,P.cream,a)}c.globalAlpha=Math.min(.3,state.magnetField*1.5);c.strokeStyle=P.gold;c.lineWidth=1.5;c.beginPath();c.arc(0,0,9+level,0,Math.PI*2);c.stroke();c.restore()}
function drawSelection(c,g,selected,hover,inspected,T){const def=PLANTS.find(p=>p.id===selected),focus=inspected&&g.plants.includes(inspected)?inspected:hover&&def?{...def,x:Math.floor(hover.x),y:Math.floor(hover.y)}:null;if(focus&&PLANTS.some(p=>p.id===focus.id)){c.save();c.beginPath();c.arc((focus.x+.5)*T,(focus.y+.5)*T,g.stats(focus).range*T,0,Math.PI*2);c.globalAlpha=.12;c.fillStyle=P.cream;c.fill();c.globalAlpha=.6;c.strokeStyle=P.cream;c.lineWidth=1;c.stroke();c.restore()}if(hover&&selected){const x=Math.floor(hover.x),y=Math.floor(hover.y),tool=selected==='shovel'||selected==='remote';c.save();c.globalAlpha=.3;c.fillStyle=(tool?g.occupied(x,y):g.valid(x,y))?P.cream:P.damage;c.fillRect(x*T,y*T,T,T);c.restore()}if(selected==='shovel'){c.save();c.strokeStyle=P.gold;c.lineWidth=1.5;for(const p of g.plants)c.strokeRect(p.x*T+3,p.y*T+3,T-6,T-6);c.restore()}}
export function render(ctx,g,selected,hover,inspected,dt=1/60){let visual=states.get(g);if(!visual){visual=new VisualState(g);states.set(g,visual)}visual.update(dt);const T=MAP.tileSize,W=MAP.cols*T,H=MAP.rows*T,time=visual.time;ctx.clearRect(0,0,W,H);ctx.save();const reduce=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;const shake=reduce?0:visual.shake;ctx.translate(Math.sin(time*73)*shake,Math.cos(time*89)*shake*.65);drawTerrain(ctx,g,time);drawMagnetField(ctx,g,visual,T);drawSelection(ctx,g,selected,hover,inspected,T);drawSynergies(ctx,g,T);for(const zone of g.zones)drawZone(ctx,zone,T,time);
 const entities=[...visual.entities.values(),...visual.ghosts];entities.push({kind:'base',y:MAP.basePosition.centerY*T});entities.sort((a,b)=>a.y-b.y);for(const v of entities){if(v.kind==='base')drawBase(ctx,g,time);else drawEntity(ctx,v,visual,T,inspected)}
 for(const shot of g.shots)drawProjectile(ctx,shot,T,time,visual.shots.get(shot));for(const effect of g.effects)drawEffect(ctx,effect,T,time);visual.particles.draw(ctx);for(const l of visual.links){const progress=(time-l.born)/.3;ctx.save();ctx.globalAlpha=1-progress;if(l.type==='pierce')line(ctx,[[l.x,l.y],[l.tx,l.ty]],P.light,2);else if(l.type==='fragment')leaf(ctx,l.x+(l.tx-l.x)*progress,l.y+(l.ty-l.y)*progress,5,progress*7);else oval(ctx,l.x+(l.tx-l.x)*progress,l.y+(l.ty-l.y)*progress,3,3,P.green);ctx.restore()}
 // Telegraphs are drawn above decorative effects; Suns stay above the world.
 for(const z of g.zombies)drawTelegraph(ctx,z,T,time);for(const sun of g.sunDrops)drawSun(ctx,sun,T,time,hover&&Math.hypot(sun.x-hover.x,sun.y-hover.y)<BALANCE.pickupRadius);ctx.restore();
 if(g.state==='intermission'&&g.nextWavePlan){ctx.save();ctx.fillStyle=P.ink;ctx.font='bold 11px system-ui';ctx.textAlign='center';const labels={north:'↓ NORTH',east:'← EAST',south:'↑ SOUTH',west:'→ WEST'},positions={north:[W/2,18],east:[W-34,H/2],south:[W/2,H-12],west:[35,H/2]};for(const edge of g.nextWavePlan.spawnEdges)if(positions[edge])ctx.fillText(labels[edge],...positions[edge]);ctx.restore()}if(g.paused){ctx.save();ctx.fillStyle=P.shadow;ctx.fillRect(0,0,W,H);ctx.fillStyle=P.cream;ctx.font='bold 28px system-ui';ctx.textAlign='center';ctx.fillText('PAUSADO',W/2,H/2);ctx.restore()}
}
